import {mountChat,stopChat} from './chat.js';
import * as api from './api.js';
import {escapeHTML as e,csv,dateTime,bytes,validateAPK,sha256,allPages} from './utils.js';
const $=s=>document.querySelector(s);
const state={profile:null,view:'Dashboard',page:0,rows:[],lookups:{},filters:{},busy:false};
const views=['Dashboard','Projects','Applications','Builds','QA Testing','Bug Reports','My Queue','Notifications','Reports','QA Summaries','Chat','Team','Settings','Account'];
const tableMap={'Projects':'projects','Applications':'applications','Builds':'builds','QA Testing':'test_sessions','Bug Reports':'bugs','My Queue':'bugs','Notifications':'notifications','QA Summaries':'qa_summaries','Team':'profiles'};
const title=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const badge=v=>`<span class="badge ${e(v)}">${e(title(v))}</span>`;
const admin=()=>state.profile?.role==='admin',qa=()=>['qa','admin'].includes(state.profile?.role),dev=()=>['developer','admin'].includes(state.profile?.role);
const person=id=>state.lookups.profiles?.find(x=>x.id===id)?.full_name||state.lookups.profiles?.find(x=>x.id===id)?.email||id||'Unassigned';
const appName=id=>state.lookups.applications?.find(x=>x.id===id)?.app_name||id||'—';
const projectName=id=>state.lookups.projects?.find(x=>x.id===id)?.project_name||id||'—';
const options=(rows,label,selected='')=>rows.map(r=>`<option value="${e(r.id)}" ${r.id===selected?'selected':''}>${e(typeof label==='function'?label(r):r[label])}</option>`).join('');
const enumOptions=(values,selected='')=>values.map(v=>`<option value="${e(v)}" ${v===selected?'selected':''}>${e(title(v))}</option>`).join('');
const field=(name,label,value='',type='text',required=false)=>`<label>${e(label)}<input name="${name}" type="${type}" value="${e(value)}" ${required?'required':''}></label>`;
const area=(name,label,value='',required=false)=>`<label class="full">${e(label)}<textarea name="${name}" ${required?'required':''}>${e(value)}</textarea></label>`;
const select=(name,label,html)=>`<label>${e(label)}<select name="${name}" required>${html}</select></label>`;
function notify(message,error=false){$('#toast').textContent=message;$('#toast').classList.add('show');$('#toast').style.background=error?'#803b33':'#123f34';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),8000);}
async function action(fn){if(state.busy)return;state.busy=true;try{await fn();}catch(err){notify(err.message,true);}finally{state.busy=false;}}
function modal(name,html,submit){$('#modal-title').textContent=name;$('#modal-body').innerHTML=html;$('#modal').showModal();const form=$('#modal form');if(form&&['Report a bug','QA final summary'].includes(name)){form.draftKey='pmt.draft.'+state.profile.id+'.'+name;let draft={};try{draft=JSON.parse(sessionStorage.getItem(form.draftKey)||'{}');}catch{}for(const [key,value] of Object.entries(draft))if(form.elements[key]&&form.elements[key].type!=='file')form.elements[key].value=value;form.bugID=draft.__id||crypto.randomUUID();form.addEventListener('input',()=>{const draft={__id:form.bugID};for(const [key,value] of new FormData(form))if(typeof value==='string')draft[key]=value;sessionStorage.setItem(form.draftKey,JSON.stringify(draft));});}if(form)form.addEventListener('submit',async ev=>{ev.preventDefault();if(form.dataset.busy)return;form.dataset.busy='1';const buttons=[...form.querySelectorAll('button[type="submit"]')];buttons.forEach(b=>b.disabled=true);let error=form.querySelector('.form-error');if(!error){error=document.createElement('p');error.className='error form-error';form.append(error);}error.textContent='';try{await submit(Object.fromEntries(new FormData(form)),form);}catch(err){error.textContent=err.message;}finally{delete form.dataset.busy;buttons.forEach(b=>b.disabled=false);}});}
function form(content,label='Save'){return `<form><div class="form-grid">${content}</div><div class="form-footer"><button type="submit" class="primary">${label}</button></div></form>`;}
$('#close-modal').onclick=()=>{if($('#modal form')?.dataset.busy){notify('Please wait for this operation to finish.');return;}$('#modal').close();};
$('#modal').addEventListener('cancel',ev=>{if($('#modal form')?.dataset.busy)ev.preventDefault();});
window.addEventListener('pmt:expired',()=>{notify('Your session expired. Sign in again.',true);login();});
function downloadFile(content,name,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function loadLookups(){for(const table of ['projects','applications','profiles'])state.lookups[table]=await allPages((offset,size)=>api.list(table,`select=*&order=id&offset=${offset}&limit=${size}`));}
function login(){stopChat();state.profile=null;$('#app').innerHTML=`<div class="login"><section class="login-aside"><div class="eyebrow">PMT / COMPANY WORKSPACE</div><h1>Better builds.<br>Clearer feedback.</h1><p>One place for your projects, release history and every detail that makes your next build better.</p><p>PROJECTS &nbsp; / &nbsp; BUILDS &nbsp; / &nbsp; QUALITY</p></section><section class="login-box"><div class="brand"><b>P</b> PMT</div><h1>Welcome back</h1><p class="muted">Sign in to your team's workspace.</p><form id="login-form">${field('email','Work email','','email',true)}${field('password','Password','','password',true)}<button class="primary" type="submit">Sign in →</button><p class="error" id="login-error"></p></form><button class="link" id="reset-password">Forgot your password?</button><p class="muted">Accounts are managed by your Admin.</p></section></div>`;
 $('#login-form').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button');button.disabled=true;try{const values=Object.fromEntries(new FormData(ev.target));const session=await api.auth('token?grant_type=password',values);api.saveSession(session);await start();}catch(err){$('#login-error')&&($('#login-error').textContent=err.message);}finally{button.disabled=false;}};
 $('#reset-password').onclick=()=>action(async()=>{const email=$('[name=email]').value;const redirect=location.href.split('#')[0];if(!email)throw Error('Enter your work email first.');await api.auth('recover',{email,redirect_to:redirect});notify('If this account exists, recovery instructions will be sent. Email delivery depends on Admin SMTP configuration.');});
}
async function start(){if(!api.currentSession())return login();try{const profiles=await api.list('profiles','id=eq.'+api.currentSession().user.id);state.profile=profiles[0];if(!state.profile?.is_active)throw Error('Your account is inactive. Contact Admin.');await loadLookups();shell();await render();}catch(err){api.saveSession(null);login();$('#login-error').textContent=err.message;}}
function shell(){const visible=views.filter(v=>!(['Team','Settings'].includes(v)&&!admin())&&!(v==='My Queue'&&!dev()));$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><b>P</b><div>PMT<small>Workspace</small></div></div><div class="eyebrow muted">WORKSPACE</div><nav>${visible.map(v=>`<button data-view="${v}">${e(v)}</button>`).join('')}</nav><footer><strong>${e(state.profile.full_name||state.profile.email)}</strong><p class="role">${e(state.profile.role)}</p><button id="logout">Sign out</button></footer></aside><div><header class="topbar"><span>Workspace &nbsp; / &nbsp; <b id="breadcrumb">Dashboard</b></span><div class="actions"><span>${e(state.profile.email)}</span><button data-view="Notifications" aria-label="Notifications">Notifications</button><button id="refresh">↻ Refresh</button><button id="mobile-logout">Sign out</button></div></header><main class="main" id="main"></main></div></div>`;
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#logout').onclick=$('#mobile-logout').onclick=()=>action(async()=>{await api.signOut();login();});$('#refresh').onclick=()=>action(async()=>{await loadLookups();await render();});
}
async function navigate(view){if(state.busy)return;state.view=view;state.page=0;state.filters={};await action(render);}
function header(description,actions=''){return `<div class="page-head"><div><div class="eyebrow muted">YOUR WORKSPACE</div><h1>${e(state.view)}</h1><p>${e(description)}</p></div><div class="actions">${actions}</div></div>`;}
async function render(){stopChat();if(!state.profile)return;$('#breadcrumb').textContent=state.view;document.querySelectorAll('nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#main').innerHTML='<div class="loading">Loading records…</div>';if(state.view==='Chat')return mountChat($('#main'),state.profile,state.lookups.projects);if(state.view==='Dashboard')return dashboard();if(state.view==='Reports')return reports();if(state.view==='Settings')return settings();if(state.view==='Account')return account();return records();}
async function count(table,filter=''){const response=await api.request('/rest/v1/'+table+'?select=id&limit=0'+filter,{headers:{Prefer:'count=exact'}}).catch(()=>null);return response;}
async function dashboard(){const [bugs,builds,projects,logs]=await Promise.all([api.rpc('pmt_dashboard'),api.list('builds','order=created_at.desc&limit=6'),api.list('projects','order=created_at.desc&limit=5'),api.list('activity_logs','order=occurred_at.desc&limit=8')]);const totals=bugs;$('#main').innerHTML=header('A clear view of projects, builds and quality.',qa()?'<button class="primary" id="new-bug">+ Report a bug</button>':'')+`<div class="cards">${[['Active projects',totals.projects,'PROJECT PORTFOLIO'],['Builds awaiting QA',totals.awaiting_qa,'RELEASE PIPELINE'],['Open bugs',totals.open_bugs,'NEEDS ATTENTION'],['Ready for retest',totals.retest,'QUALITY CHECK']].map(([label,note,accent])=>`<article class="card"><span class="accent">${accent}</span><strong>${e(note??0)}</strong><span class="muted">${label}</span></article>`).join('')}</div><div class="grid"><section class="panel"><div class="panel-head"><h2>Latest builds</h2><button class="link" id="all-builds">View all →</button></div>${buildTable(builds)}</section><section class="panel"><h2>Quality snapshot</h2>${[['Critical bugs',totals.critical],['Pending bugs',totals.pending],['Closed bugs',totals.closed],['Total builds',totals.builds],['QA passed',totals.passed],['QA failed',totals.failed]].map(([k,v])=>`<div class="row"><span>${k}</span><strong>${e(v??0)}</strong></div>`).join('')}</section></div><div class="grid"><section class="panel"><h2>Recent activity</h2>${timeline(logs)}</section><section class="panel"><h2>Projects in focus</h2>${projects.map(p=>`<div class="row"><strong>${e(p.project_name)}</strong>${badge(p.status)}</div>`).join('')||empty('No projects yet. Admin can create your first project.')}</section></div>`;$('#new-bug')?.addEventListener('click',()=>action(()=>bugForm()));$('#all-builds').onclick=()=>navigate('Builds');bindDetails();mountAdminControls();}
function empty(message='No records match these filters.'){return `<div class="empty">${e(message)}</div>`;}
function timeline(logs){return logs.length?`<ul class="timeline">${logs.map(l=>`<li><strong>${e(title(l.event_type||l.to_status||l.result||l.outcome||'Update'))}</strong><small>${e(person(l.actor_id||l.changed_by||l.qa_user_id))} · ${e(dateTime(l.occurred_at||l.created_at||l.changed_at||l.assigned_at||l.retested_at))}</small>${l.reason||l.notes?`<p>${e(l.reason||l.notes)}</p>`:''}</li>`).join('')}</ul>`:empty('No activity recorded yet.');}
function table(columns,rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${columns.map(c=>`<th>${e(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(cell=>'<td>'+cell+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`:empty();}
const detailButton=(table,id,label)=>`<button class="link" data-detail="${table}" data-id="${e(id)}">${e(label)}</button>`;
function buildTable(rows){return table(['Build / application','Status','Uploaded','File'],rows.map(b=>[detailButton('builds',b.id,b.version_name+' · #'+b.version_code)+`<small>${e(appName(b.application_id))}</small>`,badge(b.status),e(dateTime(b.created_at)),e(b.file_state==='removed'?'File removed':bytes(b.file_size))]));}
function queryFor(view,offset=state.page*25,limit=25){let q='select=*&order='+(view==='Team'?'created_at.desc,id':'created_at.desc,id')+`&offset=${offset}&limit=${limit}`;if(view==='My Queue')q+='&assigned_developer_id=eq.'+state.profile.id;const f=state.filters;const search=(f.search||'').replace(/[(),.*%_]/g,' ').trim();if(search){const fields={Projects:['project_name'],Applications:['app_name','package_name'],Builds:['version_name'], 'Bug Reports':['title','bug_code'],'My Queue':['title','bug_code'],Team:['full_name','email'],'QA Summaries':['title'],Notifications:['message']}[view];if(fields)q+='&or=('+fields.map(k=>k+'.ilike.'+encodeURIComponent('*'+search+'*')).join(',')+')';}if(f.status)q+='&status=eq.'+encodeURIComponent(f.status);if(f.application_id)q+='&application_id=eq.'+encodeURIComponent(f.application_id);if(f.project_id){const ids=state.lookups.applications.filter(a=>a.project_id===f.project_id).map(a=>a.id);q+='&application_id=in.('+ids.join(',')+')';}if(f.affected_build_id)q+='&affected_build_id=eq.'+f.affected_build_id;if(f.assigned_developer_id)q+='&assigned_developer_id=eq.'+f.assigned_developer_id;if(f.reported_after)q+='&created_at=gte.'+encodeURIComponent(f.reported_after+'T00:00:00+05:00');if(f.priority)q+='&priority=eq.'+f.priority;if(f.severity)q+='&severity=eq.'+f.severity;return q;}
async function records(){const view=state.view,tableName=tableMap[view];const rows=await api.list(tableName,queryFor(view));state.rows=rows;let create='';if(view==='Projects'&&admin())create='New project';if(view==='Applications'&&admin())create='New application';if(view==='Builds'&&dev())create='Upload APK';if(['Bug Reports','My Queue'].includes(view)&&qa())create='Report a bug';if(view==='Team'&&admin())create='Add account';if(view==='QA Summaries'&&qa())create='Write / upload summary';const isBugs=['Bug Reports','My Queue'].includes(view);let filters=`<input id="search" aria-label="Search" placeholder="Search ${e(view.toLowerCase())}…" value="${e(state.filters.search||'')}">`;
 if(isBugs||view==='Builds'){filters+=`<select id="filter-status" aria-label="Filter status"><option value="">All statuses</option>${enumOptions(isBugs?['open','in_progress','pending','not_a_bug','ready_for_retest','reopened','closed']:['uploaded','awaiting_qa','assigned_to_qa','testing','qa_passed','qa_failed','fix_required','retesting','archived'],state.filters.status)}</select><select id="filter-app" aria-label="Filter application"><option value="">All applications</option>${options(state.lookups.applications,'app_name',state.filters.application_id)}</select>`;}
 if(isBugs)filters+=`<select id="filter-priority" aria-label="Filter priority"><option value="">All priorities</option>${enumOptions(['high','medium','low'],state.filters.priority)}</select><select id="filter-severity" aria-label="Filter severity"><option value="">All severities</option>${enumOptions(['critical','major','minor','trivial'],state.filters.severity)}</select>`;
 if(isBugs){filters+='<select id="filter-project" aria-label="Filter project"><option value="">All projects</option>'+options(state.lookups.projects,'project_name',state.filters.project_id)+'</select><select id="filter-developer" aria-label="Filter developer"><option value="">All developers</option>'+options(state.lookups.profiles.filter(p=>p.role==='developer'),'full_name',state.filters.assigned_developer_id)+'</select><input id="filter-build" aria-label="Affected build ID" placeholder="Affected build ID" value="'+e(state.filters.affected_build_id||'')+'"><label>Reported on/after<input id="filter-date" type="date" value="'+e(state.filters.reported_after||'')+'"></label>';}
 let content;
 if(view==='Builds')content=buildTable(rows);
 else if(isBugs)content=table(['Bug / title','Application','Status','Priority / severity','Assigned to','Reported date & time'],rows.map(b=>[detailButton('bugs',b.id,b.bug_code)+`<small>${e(b.title)}</small>`,e(appName(b.application_id)),badge(b.status),badge(b.priority)+' '+badge(b.severity),e(person(b.assigned_developer_id)),e(dateTime(b.created_at))]));
 else if(view==='Projects')content=table(['Project','Status','Created','Actions'],rows.map(p=>[detailButton('projects',p.id,p.project_name),badge(p.status),e(dateTime(p.created_at)),admin()?`<button data-edit="projects" data-id="${e(p.id)}">Edit</button>`:'']));
 else if(view==='Applications')content=table(['Application','Package','Project','Actions'],rows.map(a=>[e(a.app_name),e(a.package_name),e(projectName(a.project_id)),admin()?`<button data-edit="applications" data-id="${e(a.id)}">Edit</button>`:'']));
 else if(view==='Team')content=table(['Name','Email','Role','Active','Actions'],rows.map(p=>[e(p.full_name),e(p.email),badge(p.role),p.is_active?'Yes':'No',`<button data-edit="profiles" data-id="${e(p.id)}">Manage</button>`]));
 else if(view==='QA Testing')content=table(['Build','Tester','Result','Notes','Recorded'],rows.map(t=>[detailButton('builds',t.build_id,t.build_id.slice(0,8)),e(person(t.qa_user_id)),badge(t.result),e(t.notes),e(dateTime(t.created_at))]));
 else if(view==='Notifications')content=table(['Notification','Received','Read','Action'],rows.map(n=>[e(n.message),e(dateTime(n.created_at)),n.is_read?'Yes':'No',`<button data-notification="${e(n.id)}">Open</button>`]));
 else content=table(['Title','Project','Author','Version saved'],rows.map(s=>[detailButton('qa_summaries',s.id,s.title),e(projectName(s.project_id)),e(person(s.author_id)),e(dateTime(s.created_at))]));
 $('#main').innerHTML=header(view==='Builds'?'Permanent build records. Supabase first, private Drive fallback.':view==='QA Summaries'?'Write a final report, upload evidence, or review an AI draft.':'Saved records, scoped to your access.',`${isBugs?'<button id="export-bugs">Export full CSV</button>':''}${create?`<button class="primary" id="create">+ ${create}</button>`:''}`)+`<section class="panel"><div class="filters">${filters}<button id="apply-filters">Apply</button></div>${content}<div class="pager"><span class="muted">Page ${state.page+1} · ${rows.length} records</span><div class="actions"><button id="previous" ${state.page===0?'disabled':''}>← Previous</button><button id="next" ${rows.length<25?'disabled':''}>Next →</button></div></div></section>`;
 $('#apply-filters').onclick=()=>action(async()=>{state.filters={search:$('#search').value,status:$('#filter-status')?.value,application_id:$('#filter-app')?.value,priority:$('#filter-priority')?.value,severity:$('#filter-severity')?.value,project_id:$('#filter-project')?.value,affected_build_id:$('#filter-build')?.value,assigned_developer_id:$('#filter-developer')?.value,reported_after:$('#filter-date')?.value};state.page=0;await records();});$('#search').onkeydown=ev=>{if(ev.key==='Enter')$('#apply-filters').click();};$('#previous').onclick=()=>action(async()=>{state.page--;await records();});$('#next').onclick=()=>action(async()=>{state.page++;await records();});
 $('#create')?.addEventListener('click',()=>({Projects:()=>projectForm(),Applications:()=>applicationForm(),Builds:()=>buildForm(),'Bug Reports':()=>bugForm(),'My Queue':()=>bugForm(),Team:()=>teamForm(),'QA Summaries':()=>summaryForm()}[view])());$('#export-bugs')?.addEventListener('click',()=>action(exportBugs));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const r=rows.find(x=>x.id===b.dataset.id);({projects:projectForm,applications:applicationForm,profiles:teamForm}[b.dataset.edit])(r);});document.querySelectorAll('[data-notification]').forEach(b=>b.onclick=()=>action(async()=>{const n=rows.find(x=>x.id===b.dataset.notification);await api.update('notifications',n.id,{is_read:true});if(n.bug_id)await bugDetail(n.bug_id);else if(n.build_id)await buildDetail(n.build_id);else if(n.project_id)await projectDetail(n.project_id);else await records();}));bindDetails();mountAdminControls();}
function bindDetails(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>action(()=>({bugs:bugDetail,builds:buildDetail,projects:projectDetail,qa_summaries:summaryDetail}[b.dataset.detail])(b.dataset.id)));}
async function saved(message='Saved.'){ const draftKey=$('#modal form')?.draftKey;if(draftKey)sessionStorage.removeItem(draftKey);$('#modal').close();notify(message);await loadLookups();await render();}
function projectForm(row={}){modal(row.id?'Edit project':'New project',form(field('project_name','Project name',row.project_name,'text',true)+select('status','Status',enumOptions(['active','on_hold','completed','archived'],row.status||'active'))+area('description','Description',row.description)+area('notes','Project notes',row.notes)),async data=>{if(row.id)await api.update('projects',row.id,data);else await api.insert('projects',{...data,created_by:state.profile.id});await saved();});}
function applicationForm(row={}){modal(row.id?'Edit application':'New application',form(select('project_id','Project',options(state.lookups.projects,'project_name',row.project_id))+field('app_name','Application name',row.app_name,'text',true)+field('package_name','Package name',row.package_name,'text',true)+area('description','Description',row.description)),async data=>{if(row.id)await api.update('applications',row.id,data);else await api.insert('applications',data);await saved();});}
function teamForm(row={}){modal(row.id?'Manage team member':'Create team account',form(field('full_name','Full name',row.full_name,'text',true)+(row.id?'':field('email','Email','','email',true)+field('password','Temporary password (12+ characters)','','password',true))+select('role','Role',enumOptions(['developer','qa','admin'],row.role||'developer'))+(row.id?select('is_active','Account access','<option value="true">Active</option><option value="false">Inactive</option>')+select('chat_enabled','Company chat access','<option value="true">Approved</option><option value="false">Not approved</option>'):'')+'<p class="full muted">Share temporary passwords through your company’s approved secure channel. The user can change their password in their profile.</p>'),async data=>{if(row.id){data.is_active=data.is_active==='true';data.chat_enabled=data.chat_enabled==='true';if(row.id===state.profile.id&&(data.role!=='admin'||!data.is_active))throw Error('Another Admin must change your own access.');await api.update('profiles',row.id,data);}else{if(data.password.length<12)throw Error('Use at least 12 characters.');await api.edge('invite',data);}await saved();});if(row.id){$('[name=is_active]').value=String(row.is_active);$('[name=chat_enabled]').value=String(!!row.chat_enabled);}}
async function projectDetail(id){const p=(await api.list('projects','id=eq.'+id))[0];if(!p)throw Error('Project not accessible');const members=await api.list('project_members','project_id=eq.'+id);modal(p.project_name,`<p>${e(p.description||'No description')}</p><p class="pre">${e(p.notes)}</p>${badge(p.status)}<h3>Project members</h3>${members.map(m=>`<div class="row"><span>${e(person(m.user_id))}</span>${admin()?`<button data-remove-member="${m.id}">Remove</button>`:''}</div>`).join('')||empty('No members assigned.')}${admin()?form(select('user_id','Add project member',options(state.lookups.profiles.filter(x=>x.is_active),'full_name')),'Add member'):''}`,async data=>{await api.insert('project_members',{project_id:id,user_id:data.user_id});await saved('Project member added.');});document.querySelectorAll('[data-remove-member]').forEach(b=>b.onclick=()=>action(async()=>{if(!confirm('Remove this member’s project access?'))return;await api.request('/rest/v1/project_members?id=eq.'+b.dataset.removeMember,{method:'DELETE'});await projectDetail(id);}));}
