function attachmentForm(bug){modal('Upload bug evidence',form('<label class="full">Screenshot or video<input name="file" type="file" accept="image/png,image/jpeg,image/webp,video/mp4,video/webm" required></label><p class="muted full">Screenshots up to 10 MB; videos up to 50 MB. Evidence stays private.</p><progress class="full" id="evidence-progress" max="100" value="0"></progress>','Upload evidence'),async(data,formEl)=>{const file=formEl.elements.file.files[0];const image=['image/png','image/jpeg','image/webp'].includes(file.type),video=['video/mp4','video/webm'].includes(file.type);if(!image&&!video)throw Error('Select PNG, JPEG, WebP, MP4 or WebM.');if(file.size>(image?10:50)*1024*1024)throw Error('File exceeds the attachment size limit.');const head=new Uint8Array(await file.slice(0,16).arrayBuffer());if(image&&!((head[0]===137&&head[1]===80)||(head[0]===255&&head[1]===216)||(new TextDecoder().decode(head.slice(0,4))==='RIFF'&&new TextDecoder().decode(head.slice(8,12))==='WEBP')))throw Error('Image contents do not match the selected type.');const bucket=image?'bug-screenshots':'bug-videos';const path=bug.id+'/'+state.profile.id+'/'+crypto.randomUUID()+'-'+file.name.replace(/[^a-z0-9._-]/gi,'_');await api.upload(bucket,path,file,n=>$('#evidence-progress').value=n);await api.insert('bug_attachments',{bug_id:bug.id,uploaded_by:state.profile.id,bucket_name:bucket,storage_path:path,file_name:file.name,mime_type:file.type,file_size:file.size});await saved('Private evidence uploaded.');});}
