 $('#ai-summary').onclick=()=>action(async()=>{const f=$('#modal form');const project=f.elements.project_id.value;$('#summary-ai-state').textContent='Reading all project bugs, builds and testing records…';const apps=state.lookups.applications.filter(a=>a.project_id===project).map(a=>a.id);if(!apps.length)throw Error('This project has no applications.');const allBugs=await allPages((o,n)=>api.list('bugs',`application_id=in.(${apps.join(',')})&order=id&offset=${o}&limit=${n}`));const allBuilds=await allPages((o,n)=>api.list('builds',`application_id=in.(${apps.join(',')})&order=id&offset=${o}&limit=${n}`));const sessions=await allPages((o,n)=>api.list('test_sessions',`order=id&offset=${o}&limit=${n}`));const evidence={project:projectName(project),bugs:allBugs,builds:allBuilds,test_sessions:sessions.filter(s=>allBuilds.some(b=>b.id===s.build_id))};const input=JSON.stringify(evidence);if(input.length>120000)throw Error('Project exceeds AI input limit. Export CSV and write a scoped summary; records are not silently truncated.');$('#summary-ai-state').textContent='Generating draft; this may take a moment…';try{const d=await api.edge('ai',{kind:'summary',project_id:project,input});f.elements.body.value=d.text;f.aiGenerated=true;$('#summary-ai-state').textContent='AI draft ready. Review, edit and approve before saving.';}catch(err){$('#summary-ai-state').textContent=err.message;throw err;}});
